fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let mut result: Vec<i32> = Vec::with_capacity(a.len());
    let mut i: usize = 0;
    let n = a.len();

    while i < n {
        // push a 1 for each element in the input vector
        result.push(1);
        i += 1;
    }

    result
}